const b = $input.first().json.body ?? $input.first().json;
const ts = b.timestamp ? new Date(b.timestamp * 1000).toISOString() : new Date().toISOString();
const score = Number(b.confidence_score ?? 0);
const pct = (score * 100).toFixed(1);
// Telegram parse_mode is HTML, so < > & in telemetry values must be escaped.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const service = esc(b.service_name ?? 'unknown');
const type = esc(b.anomaly_type ?? 'unknown');
const status = esc(b.status ?? 'ANOMALY_DETECTED');
const rcService = esc(b.root_cause_service ?? 'Investigating...');
const rcFault = esc(b.root_cause_fault_type ?? 'n/a');
const rawService = b.service_name ?? 'unknown';
const rawType = b.anomaly_type ?? 'unknown';
const rawStatus = b.status ?? 'ANOMALY_DETECTED';
const rawRcService = b.root_cause_service ?? 'Investigating...';
const rawRcFault = b.root_cause_fault_type ?? 'n/a';
const rawScore = b.anomaly_score ?? 'n/a';
return [{
  json: {
    service_name:     rawService,
    anomaly_type:     rawType,
    confidence_score: score,
    timestamp:        ts,
    status:           rawStatus,
    anomaly_score:    b.anomaly_score ?? null,
    root_cause_service:    b.root_cause_service ?? null,
    root_cause_fault_type: b.root_cause_fault_type ?? null,
    score_pct: pct,
    telegram_text: `\ud83d\udea8 <b>Sentinelas Anomaly Alert</b>\n\n<b>Service:</b> ${service}\n<b>Type:</b> ${type}\n<b>Confidence:</b> ${pct}%\n<b>Status:</b> ${status}\n<b>Time:</b> ${ts}\n<b>Root Cause:</b> ${rcService} \u2014 ${rcFault}`,
    email_subject: `[Sentinelas] Anomaly in ${rawService} (${pct}% confidence)`,
    email_body: `Sentinelas Anomaly Detected\n\nService: ${rawService}\nAnomaly Type: ${rawType}\nConfidence: ${pct}%\nStatus: ${rawStatus}\nTimestamp: ${ts}\nRoot Cause Service: ${rawRcService}\nRoot Cause Fault: ${rawRcFault}\nAnomaly Score: ${rawScore}\n\n-- Sentinelas AIOps Platform`
  }
}];
